def is_valid_batch_code(code):
    if not isinstance(code, str) or len(code) != 12:
        return False
    if not code.startswith("BT-") or code[5] != "-" or code[10] != "-":
        return False
    year, hexpart, check = code[3:5], code[6:10], code[11]
    if not (year.isdigit() and 20 <= int(year) <= 39):
        return False
    if any(ch not in "0123456789ABCDEF" for ch in hexpart):
        return False
    total = sum(int(ch, 16) for ch in hexpart)
    return check == chr(ord("A") + total % 26)
